BEGIN
-- Create a temp table to store the select results CREATE TABLE #PageIndex ( [IndexId] int IDENTITY (1, 1) NOT NULL, [ViajeHotelID] uniqueidentifier )
-- Insert into the temp table INSERT INTO #PageIndex ( [ViajeHotelID] ) SELECT TOP {3} [ViajeHotelID] FROM [dbo].[ViajeHotel] {0} ORDER BY {1}
-- Return paged results SELECT O.[ViajeHotelID], O.[ViajeID], O.[HotelID], O.[Desde], O.[Hasta], O.[HoraIngreso], O.[HoraSalida] FROM [dbo].[ViajeHotel] O, #PageIndex PageIndex WHERE PageIndex.IndexId > {2} AND O.[ViajeHotelID] = PageIndex.[ViajeHotelID] ORDER BY PageIndex.IndexId
-- get total count SELECT COUNT(*) AS TotalRowCount FROM [dbo].[ViajeHotel] {0};
DROP TABLE #PageIndex END

